import argparse
import csv
import hashlib
import json
import os
import random
import sys
from pathlib import Path


ADAPTER_NAME = 'naiveBayesClassifier_framework_api_adapter'


def parse_args():
    p = argparse.ArgumentParser()
    p.add_argument('--dataset', required=True)
    p.add_argument('--output-dir', required=True)
    p.add_argument('--limit', type=int, required=True)
    p.add_argument('--repo-root', required=True)
    p.add_argument('--seed', type=int, default=0)
    return p.parse_args()


def sha256_file(path):
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        while True:
            chunk = f.read(1024 * 1024)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def load_jsonl(path, limit):
    rows = []
    with open(path, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            rows.append(json.loads(line))
            if limit is not None and len(rows) >= limit:
                break
    return rows


def load_csv(path, limit):
    rows = []
    with open(path, 'r', encoding='utf-8', newline='') as f:
        reader = csv.DictReader(f)
        if not reader.fieldnames:
            return rows
        lower = {name.lower(): name for name in reader.fieldnames}
        review_key = lower.get('review')
        label_key = lower.get('label')
        if review_key is None or label_key is None:
            return rows
        for item in reader:
            review = item.get(review_key)
            label = item.get(label_key)
            if review is None or label is None:
                continue
            rows.append({'review': review, 'label': label})
            if limit is not None and len(rows) >= limit:
                break
    return rows


def candidate_labeled_paths(dataset_path, repo_root):
    dataset = Path(dataset_path)
    repo = Path(repo_root)
    names_jsonl = ['validation.jsonl', 'train.jsonl', 'test.jsonl', 'dataset.jsonl']
    names_csv = ['01-reviews.csv', 'reviews.csv', 'validation.csv', 'train.csv']
    candidates = []
    for name in names_jsonl + names_csv:
        candidates.append(dataset.parent / name)
    bases = [repo, repo.parent, Path.cwd(), Path.cwd().parent]
    for base in bases:
        for name in names_jsonl:
            candidates.append(base / '.research-assistant' / 'benchmark' / 'dataset' / name)
        for name in names_csv:
            candidates.append(base / '.research-assistant' / 'uploads' / name)
    seen = set()
    result = []
    for c in candidates:
        key = str(c.resolve()) if c.exists() else str(c)
        if key in seen:
            continue
        seen.add(key)
        if c.exists() and c.is_file():
            result.append(c)
    return result


def load_labeled_rows(path, limit):
    suffix = path.suffix.lower()
    if suffix == '.csv':
        return load_csv(path, limit)
    return [r for r in load_jsonl(path, limit) if 'review' in r and 'label' in r]


def first_prediction(classifier, text):
    result = classifier.classify(text)
    if result is None:
        return None
    if isinstance(result, dict):
        if not result:
            return None
        return sorted(result.items(), key=lambda item: item[1], reverse=True)[0][0]
    if isinstance(result, (list, tuple)):
        if not result:
            return None
        first = result[0]
        if isinstance(first, (list, tuple)):
            return first[0]
        return first
    return result


def compute_metrics(y_true, y_pred):
    if not y_true:
        return {}
    total = len(y_true)
    correct = sum(1 for t, p in zip(y_true, y_pred) if t == p)
    labels = sorted(set(y_true) | set(y_pred))
    f1_values = []
    for label in labels:
        tp = sum(1 for t, p in zip(y_true, y_pred) if t == label and p == label)
        fp = sum(1 for t, p in zip(y_true, y_pred) if t != label and p == label)
        fn = sum(1 for t, p in zip(y_true, y_pred) if t == label and p != label)
        if tp == 0:
            f1 = 0.0
        else:
            precision = tp / (tp + fp) if (tp + fp) > 0 else 0.0
            recall = tp / (tp + fn) if (tp + fn) > 0 else 0.0
            if precision + recall > 0:
                f1 = 2.0 * precision * recall / (precision + recall)
            else:
                f1 = 0.0
        f1_values.append(f1)
    macro_f1 = sum(f1_values) / len(f1_values) if f1_values else 0.0
    return {'macro_f1': float(macro_f1), 'accuracy': float(correct / total)}


def write_manifest(output_dir, status, dataset_sha256, sample_count, seed):
    manifest = {
        'status': status,
        'dataset_sha256': dataset_sha256,
        'sample_count': int(sample_count),
        'seed': int(seed),
        'adapter': ADAPTER_NAME,
    }
    path = os.path.join(output_dir, 'run_manifest.json')
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(manifest, f, ensure_ascii=False)
        f.write(chr(10))


def main():
    args = parse_args()
    random.seed(args.seed)
    os.makedirs(args.output_dir, exist_ok=True)
    dataset_sha256 = sha256_file(args.dataset)
    limit = max(0, int(args.limit))
    rows = load_jsonl(args.dataset, limit)
    sample_count = len(rows)
    metrics = {}
    status = 'ok'
    try:
        sys.path.insert(0, os.path.abspath(args.repo_root))
        from naiveBayesClassifier import tokenizer
        from naiveBayesClassifier.trainer import Trainer
        from naiveBayesClassifier.classifier import Classifier

        train_rows = [r for r in rows if 'review' in r and 'label' in r]
        if not train_rows:
            for candidate in candidate_labeled_paths(args.dataset, args.repo_root):
                try:
                    aux = load_labeled_rows(candidate, limit)
                except Exception:
                    aux = []
                if aux:
                    train_rows = aux
                    break
        if not train_rows:
            raise RuntimeError('no labeled rows available to train naiveBayesClassifier')

        train_tok = tokenizer.Tokenizer(stop_words=[], signs_to_remove=['?!#%&'])
        trainer = Trainer(train_tok)
        for item in train_rows:
            trainer.train(str(item['review']), str(item['label']))
        classify_tok = tokenizer.Tokenizer(stop_words=[], signs_to_remove=['?!#%&'])
        classifier = Classifier(trainer.data, classify_tok)

        predictions = []
        y_true = []
        y_pred = []
        for row in rows:
            if 'review' not in row:
                raise RuntimeError('dataset row missing review field')
            pred = first_prediction(classifier, str(row['review']))
            if pred is None:
                raise RuntimeError('classifier returned no prediction')
            pred = str(pred)
            out = {}
            if '__benchmark_id' in row:
                out['id'] = row['__benchmark_id']
            out['prediction'] = pred
            if 'label' in row and row['label'] is not None:
                out['target'] = row['label']
                y_true.append(str(row['label']))
                y_pred.append(pred)
            predictions.append(out)
        if y_true:
            metrics = compute_metrics(y_true, y_pred)

        pred_path = os.path.join(args.output_dir, 'predictions.jsonl')
        with open(pred_path, 'w', encoding='utf-8') as f:
            for item in predictions:
                f.write(json.dumps(item, ensure_ascii=False))
                f.write(chr(10))
    except Exception:
        status = 'unsupported'
        metrics = {}
        with open(os.path.join(args.output_dir, 'predictions.jsonl'), 'w', encoding='utf-8') as f:
            pass

    with open(os.path.join(args.output_dir, 'metrics.json'), 'w', encoding='utf-8') as f:
        json.dump(metrics, f, ensure_ascii=False)
        f.write(chr(10))
    write_manifest(args.output_dir, status, dataset_sha256, sample_count, args.seed)
    summary = {
        'status': status,
        'sample_count': sample_count,
        'metrics': metrics,
        'dataset_sha256': dataset_sha256,
    }
    print(json.dumps(summary, ensure_ascii=False))


if __name__ == '__main__':
    main()

